  "email-signature": {
    "en": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Edward Calderón · Hashpass</title>\n  </head>\n  <body style=\"margin:0;padding:24px;font-family:Arial,Helvetica,sans-serif;color:#141414;\">\n    <p style=\"margin:0 0 16px 0;font-size:14px;line-height:20px;\">Hi Edward,</p>\n    <p style=\"margin:0 0 20px 0;font-size:14px;line-height:20px;\">This is a test of the Hashpass email signature.</p>\n    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"font-family:Arial,Helvetica,sans-serif;color:#141414;border-collapse:collapse;\">\n      <tr>\n        <td style=\"padding:0 16px 0 0;vertical-align:middle;\">\n          <img src=\"https://hashpass.tech/email-signature/edward-calderon-portrait.d9bcbc18d656.jpg\" width=\"76\" height=\"76\" alt=\"Edward Calderón\" style=\"display:block;width:76px;height:76px;border:0;border-radius:50%;\" />\n        </td>\n        <td style=\"vertical-align:middle;border-left:3px solid #e11b16;padding-left:16px;\">\n          <div style=\"font-size:17px;line-height:22px;font-weight:700;color:#141414;\">Edward Calderón</div>\n          <div style=\"font-size:13px;line-height:19px;color:#e11b16;font-weight:700;\">Co-founder &amp; CEO</div>\n          <div style=\"font-size:13px;line-height:19px;color:#444444;\">HASHPASS</div>\n          <div style=\"height:8px;line-height:8px;font-size:8px;\">&nbsp;</div>\n          <div style=\"font-size:12px;line-height:18px;\">\n            <a href=\"mailto:edward@hashpass.app\" style=\"color:#141414;text-decoration:none;\">edward@hashpass.app</a>\n            <span style=\"color:#b0b0b0;\">&nbsp;|&nbsp;</span>\n            <a href=\"https://hashpass.tech\" style=\"color:#141414;text-decoration:none;\">hashpass.tech</a>\n            <span style=\"color:#b0b0b0;\">&nbsp;|&nbsp;</span>\n            <a href=\"https://www.linkedin.com/in/edwardca-dev/\" style=\"color:#141414;text-decoration:none;\">LinkedIn</a>\n          </div>\n          <div style=\"height:10px;line-height:10px;font-size:10px;\">&nbsp;</div>\n          <a href=\"https://hashpass.tech\" style=\"text-decoration:none;\">\n            <img src=\"https://hashpass.tech/email-signature/hashpass-wordmark.c3bcc34c86c.png\" width=\"150\" height=\"28\" alt=\"HASHPASS\" style=\"display:block;width:150px;height:28px;border:0;\" />\n          </a>\n        </td>\n      </tr>\n    </table>\n  </body>\n</html>\n"
  },
